/**
 * Text corpora, synthetic and real: topic-model corpora generated by LDA with their true topics, labelled corpora from
 * a multinomial naive Bayes model, drifting topics over time slices, planted near-duplicates for MinHash and record
 * linkage, textbook worked examples, nursery rhymes, and Karpathy's Tiny Shakespeare as a pinned remote asset.
 */

import { argmaxOf, OmaiError, softmaxOf } from '../base/index.ts'
import {
  type CorpusData,
  corpus,
  type DatasetGenerator,
  type DatasetRef,
  type ParallelData,
  parallel,
  type SequenceLabellingData,
  sequenceLabelling,
} from '../data/index.ts'
import { categorical, dirichlet, foldIn, type Key, normal, poisson, uniform } from '../random/index.ts'
import { choice, dict, int, real } from '../space/index.ts'
import { fromStorage } from '../tensor/index.ts'
import { CAESAR_PASSAGES, DEERWESTER_TITLES, NURSERY_RHYMES } from './_data/texts.ts'
import { labels, stamp } from './_util.ts'

/** A synthetic vocabulary `w000, w001, ...`. */
function words(v: number): string[] {
  const width = String(v - 1).length
  return Array.from({ length: v }, (_, i) => `w${String(i).padStart(width, '0')}`)
}

/** The "bars" topics of Griffiths and Steyvers (2004): a 5 by 5 grid of words, each topic a row or a column. */
function barsTopics(side: number): number[][] {
  const v = side * side
  const out: number[][] = []
  for (let r = 0; r < side; r++)
    out.push(Array.from({ length: v }, (_, w) => (Math.floor(w / side) === r ? 1 / side : 0)))
  for (let c = 0; c < side; c++) out.push(Array.from({ length: v }, (_, w) => (w % side === c ? 1 / side : 0)))
  return out
}

/** Documents from a topic model: per-document topic proportions, a Poisson length, and topic-then-word draws. */
function ldaDocuments(
  k: Key,
  topics: readonly (readonly number[])[],
  nDocs: number,
  meanLength: number,
  alpha: number,
): { tokens: number[][]; theta: number[][]; z: number[][] } {
  const nTopics = topics.length
  const theta = Array.from({ length: nDocs }, (_, d) =>
    Array.from(dirichlet(foldIn(foldIn(k, 0), d), new Array(nTopics).fill(alpha), 1).data),
  )
  const lengths = Array.from(poisson(foldIn(k, 1), meanLength, [nDocs]).data, (l) => Math.max(1, l))
  const tokens: number[][] = []
  const z: number[][] = []
  for (let d = 0; d < nDocs; d++) {
    const len = lengths[d] ?? 1
    const zd = Array.from(categorical(foldIn(foldIn(k, 2), d), theta[d] as number[], [len]).data)
    const u = uniform(foldIn(foldIn(k, 3), d), [len]).data
    tokens.push(
      zd.map((t, i) => {
        const row = topics[t] ?? []
        let acc = 0
        for (const [w, p] of row.entries()) {
          acc += p
          if ((u[i] ?? 1) < acc) return w
        }
        return row.length - 1
      }),
    )
    z.push(zd)
  }
  return { tokens, theta, z }
}

/** `log p(tokens | theta, topics)` summed over the corpus (marginalising the topic of each token). */
function ldaLogLikelihood(
  tokens: readonly (readonly number[])[],
  theta: readonly (readonly number[])[],
  topics: readonly (readonly number[])[],
): number {
  let s = 0
  for (const [d, doc] of tokens.entries()) {
    for (const w of doc) {
      let p = 0
      for (const [t, row] of topics.entries()) p += (theta[d]?.[t] ?? 0) * (row[w] ?? 0)
      s += Math.log(p)
    }
  }
  return s
}

/**
 * A topic-model corpus with true topics (latent Dirichlet allocation as a generator): topics from a symmetric
 * Dirichlet over a synthetic vocabulary, or the "bars" topics of Griffiths and Steyvers (rows and columns of a word
 * grid, easy to see). Each document has Dirichlet topic proportions, a Poisson length and topic-then-word draws. The
 * truth has the topics, the proportions, every token's topic and the log-likelihood; labels are dominant topics.
 *
 * @example
 * ```ts
 * import { generate } from 'omai-engine/data'
 * import { topicCorpus } from 'omai-engine/datasets'
 * generate(topicCorpus, { knobs: { topics: 'bars', nDocs: 20 } }).data.vocabulary?.length // => 25
 * ```
 */
export const topicCorpus: DatasetGenerator<CorpusData> = {
  name: 'topicCorpus',
  kind: 'corpus',
  description: 'Documents drawn from latent Dirichlet allocation, with Dirichlet or bars topics.',
  knobs: dict({
    nDocs: int(1, 100_000, { label: 'documents', description: 'The number of documents.', default: 200 }),
    nTopics: int(1, 100, { label: 'topics', description: 'The number of topics.', default: 5 }),
    vocabulary: int(2, 100_000, {
      label: 'vocabulary size',
      description: 'The number of distinct words.',
      default: 100,
    }),
    docLength: real(1, 10_000, {
      description: 'The mean number of words per document (Poisson).',
      default: 50,
      label: 'mean document length',
    }),
    alpha: real(0.001, 100, {
      description:
        'The Dirichlet concentration of each document’s topic mix: small values give few topics per document.',
      default: 0.5,
      label: 'document-topic concentration',
    }),
    eta: real(0.001, 100, {
      description: 'The Dirichlet concentration of each topic’s word distribution: small values give peaked topics.',
      default: 0.1,
      label: 'topic-word concentration',
    }),
    topics: choice(['dirichlet', 'bars'], {
      label: 'topic shapes',
      description: 'Dirichlet-drawn topics, or the bars of a square vocabulary (easy to see).',
      default: 'dirichlet',
    }),
  }),
  generate: (k, knobs) => {
    const bars = knobs['topics'] === 'bars'
    const v = bars ? 25 : (knobs['vocabulary'] as number)
    const nTopics = bars ? 10 : (knobs['nTopics'] as number)
    const topics = bars
      ? barsTopics(5)
      : Array.from({ length: nTopics }, (_, t) =>
          Array.from(dirichlet(foldIn(foldIn(k, 0), t), new Array(v).fill(knobs['eta'] as number), 1).data),
        )
    const vocab = words(v)
    const { tokens, theta, z } = ldaDocuments(
      foldIn(k, 1),
      topics,
      knobs['nDocs'] as number,
      knobs['docLength'] as number,
      knobs['alpha'] as number,
    )
    const dominant = theta.map((row) => argmaxOf(row))
    return {
      data: corpus(
        {
          tokens,
          documents: tokens.map((doc) => doc.map((w) => vocab[w] ?? '').join(' ')),
          labels: dominant,
          classes: topics.map((_, t) => `topic${t}`),
          vocabulary: vocab,
        },
        stamp('topicCorpus', topicCorpus.description, knobs),
      ),
      truth: {
        clusters: labels(dominant),
        latents: { topics, docTopics: theta, assignments: z },
        extra: { logLikelihood: ldaLogLikelihood(tokens, theta, topics), alpha: knobs['alpha'], eta: knobs['eta'] },
      },
    }
  },
}

/**
 * A labelled toy corpus from a multinomial naive Bayes model: each class has its own word distribution (a shared
 * background plus `signal` extra mass on its own keywords), documents have Poisson lengths. The truth is the exact
 * class posterior of any token list (`truth.extra.posterior`), the class priors and word probabilities.
 *
 * @example
 * ```ts
 * import { generate } from 'omai-engine/data'
 * import { naiveBayesCorpus } from 'omai-engine/datasets'
 * generate(naiveBayesCorpus, { knobs: { nClasses: 3 } }).data.classes // => ['class0', 'class1', 'class2']
 * ```
 */
export const naiveBayesCorpus: DatasetGenerator<CorpusData> = {
  name: 'naiveBayesCorpus',
  kind: 'corpus',
  description: 'Labelled documents from a multinomial naive Bayes model with class keywords.',
  knobs: dict({
    nDocs: int(1, 100_000, { label: 'documents', description: 'The number of documents.', default: 300 }),
    nClasses: int(2, 50, { label: 'classes', description: 'The number of classes.', default: 2 }),
    vocabulary: int(10, 100_000, {
      label: 'vocabulary size',
      description: 'The number of distinct words.',
      default: 200,
    }),
    keywords: int(1, 1000, { description: 'Words specific to each class.', default: 10, label: 'keywords per class' }),
    signal: real(0, 0.99, {
      description: 'The probability mass each class puts on its keywords.',
      default: 0.3,
      label: 'probability mass on class keywords',
    }),
    docLength: real(1, 10_000, {
      label: 'mean document length',
      description: 'The mean number of words per document.',
      default: 30,
    }),
  }),
  generate: (k, knobs) => {
    const nc = knobs['nClasses'] as number
    const v = knobs['vocabulary'] as number
    const kw = Math.min(knobs['keywords'] as number, Math.floor(v / nc))
    const signal = knobs['signal'] as number
    const background = Array.from(dirichlet(foldIn(k, 0), new Array(v).fill(1), 1).data)
    const wordProbs = Array.from({ length: nc }, (_, c) =>
      background.map((p, w) => (1 - signal) * p + (w >= c * kw && w < (c + 1) * kw ? signal / kw : 0)),
    )
    const priors = new Array<number>(nc).fill(1 / nc)
    const n = knobs['nDocs'] as number
    const y = Array.from(categorical(foldIn(k, 1), priors, [n]).data)
    const lens = Array.from(poisson(foldIn(k, 2), knobs['docLength'] as number, [n]).data, (l) => Math.max(1, l))
    const tokens = y.map((c, d) =>
      Array.from(categorical(foldIn(foldIn(k, 3), d), wordProbs[c] as number[], [lens[d] ?? 1]).data),
    )
    const vocab = words(v)
    const posterior = (doc: readonly number[]): number[] => {
      const lp = wordProbs.map(
        (row, c) => Math.log(priors[c] ?? 1) + doc.reduce((s, w) => s + Math.log(row[w] ?? 1e-300), 0),
      )
      return softmaxOf(lp)
    }
    return {
      data: corpus(
        {
          tokens,
          documents: tokens.map((d) => d.map((w) => vocab[w] ?? '').join(' ')),
          labels: y,
          classes: wordProbs.map((_, c) => `class${c}`),
          vocabulary: vocab,
        },
        stamp('naiveBayesCorpus', naiveBayesCorpus.description, knobs),
      ),
      truth: { extra: { posterior, priors, wordProbabilities: wordProbs, keywords: kw } },
    }
  },
}

/**
 * Drifting topics (a dynamic topic model): topic word distributions are softmaxes of natural parameters that follow
 * Gaussian random walks across `slices` time slices, and each slice has its own LDA documents. Labels are the time
 * slice of each document; the truth has the topics of every slice.
 *
 * @example
 * ```ts
 * import { generate } from 'omai-engine/data'
 * import { driftingTopics } from 'omai-engine/datasets'
 * (generate(driftingTopics, { knobs: { slices: 4 } }).truth.latents?.['topics'] as number[][][]).length // => 4
 * ```
 */
export const driftingTopics: DatasetGenerator<CorpusData> = {
  name: 'driftingTopics',
  kind: 'corpus',
  description: 'Topic-model documents whose topics drift over time slices (a dynamic topic model).',
  knobs: dict({
    slices: int(1, 1000, { label: 'time slices', description: 'The number of time slices.', default: 5 }),
    docsPerSlice: int(1, 10_000, {
      label: 'documents per slice',
      description: 'The number of documents in each slice.',
      default: 40,
    }),
    nTopics: int(1, 50, { label: 'topics', description: 'The number of topics.', default: 3 }),
    vocabulary: int(2, 10_000, { label: 'vocabulary size', description: 'The number of distinct words.', default: 60 }),
    drift: real(0, 10, {
      description: 'The random-walk step of the topics’ natural parameters between slices.',
      default: 0.5,
      label: 'random-walk step of topic parameters',
    }),
    docLength: real(1, 10_000, {
      label: 'mean document length',
      description: 'The mean number of words per document.',
      default: 40,
    }),
    alpha: real(0.001, 100, {
      label: 'document-topic concentration',
      description: 'The Dirichlet concentration of each document’s topic mix.',
      default: 0.5,
    }),
  }),
  generate: (k, knobs) => {
    const slices = knobs['slices'] as number
    const kt = knobs['nTopics'] as number
    const v = knobs['vocabulary'] as number
    const drift = knobs['drift'] as number
    let eta = Array.from({ length: kt }, (_, t) =>
      Float64Array.from(normal(foldIn(foldIn(k, 0), t), [v]).data, (x) => 2 * x),
    )
    const topicsBySlice: number[][][] = []
    const tokens: number[][] = []
    const slice: number[] = []
    for (let s = 0; s < slices; s++) {
      if (s > 0)
        eta = eta.map((row, t) =>
          Float64Array.from(normal(foldIn(foldIn(k, 1), s * kt + t), [v]).data, (x, w) => (row[w] ?? 0) + drift * x),
        )
      const topics = eta.map((row) => softmaxOf(row))
      topicsBySlice.push(topics)
      const docs = ldaDocuments(
        foldIn(foldIn(k, 2), s),
        topics,
        knobs['docsPerSlice'] as number,
        knobs['docLength'] as number,
        knobs['alpha'] as number,
      )
      for (const doc of docs.tokens) {
        tokens.push(doc)
        slice.push(s)
      }
    }
    const vocab = words(v)
    return {
      data: corpus(
        {
          tokens,
          documents: tokens.map((d) => d.map((w) => vocab[w] ?? '').join(' ')),
          labels: slice,
          classes: Array.from({ length: slices }, (_, s) => `slice${s}`),
          vocabulary: vocab,
        },
        stamp('driftingTopics', driftingTopics.description, knobs),
      ),
      truth: { latents: { topics: topicsBySlice, slice }, extra: { drift } },
    }
  },
}

/** The worked-example corpora of {@link workedExampleCorpus}. */
export type WorkedExample = 'deerwester' | 'caesar'

/**
 * Small corpora from textbook worked examples: the nine technical memo titles of Deerwester et al. (1990), the
 * running example of latent semantic analysis (labelled human-computer interaction or graph theory), and the two Julius
 * Caesar passages of Manning, Raghavan and Schütze's inverted-index example.
 *
 * @param name - Which corpus.
 * @returns The corpus.
 * @example
 * ```ts
 * import { workedExampleCorpus } from 'omai-engine/datasets'
 * workedExampleCorpus('deerwester').documents?.length // => 9
 * ```
 */
export function workedExampleCorpus(name: WorkedExample): CorpusData {
  if (name === 'deerwester') {
    return corpus(
      {
        documents: DEERWESTER_TITLES.map((t) => t.text),
        labels: DEERWESTER_TITLES.map((t) => (t.label === 'hci' ? 0 : 1)),
        classes: ['hci', 'graphs'],
      },
      {
        name: 'deerwester',
        description: 'The nine memo titles of the latent semantic analysis worked example (Deerwester et al., 1990).',
        citation:
          'Deerwester, Dumais, Furnas, Landauer and Harshman (1990), Indexing by latent semantic analysis, JASIS 41(6).',
      },
    )
  }
  if (name === 'caesar') {
    return corpus(
      { documents: [...CAESAR_PASSAGES] },
      {
        name: 'caesar',
        description: 'Two Julius Caesar passages, the inverted-index example of Introduction to Information Retrieval.',
        citation: 'Manning, Raghavan and Schutze (2008), Introduction to Information Retrieval, chapter 1.',
        licence: 'Public domain (Shakespeare)',
      },
    )
  }
  throw new OmaiError('value', `workedExampleCorpus: unknown corpus ${String(name)}`)
}

/**
 * Sixteen traditional English nursery rhymes (public domain), one document each, titles as classes: a tiny real
 * corpus for tokenisers, n-gram models and text search.
 *
 * @returns The corpus.
 * @example
 * ```ts
 * import { nurseryRhymes } from 'omai-engine/datasets'
 * nurseryRhymes().classes?.[0] // => 'Mary Had a Little Lamb'
 * ```
 */
export function nurseryRhymes(): CorpusData {
  return corpus(
    {
      documents: NURSERY_RHYMES.map((r) => r.text),
      labels: NURSERY_RHYMES.map((_, i) => i),
      classes: NURSERY_RHYMES.map((r) => r.title),
    },
    { name: 'nurseryRhymes', description: 'Traditional English nursery rhymes.', licence: 'Public domain' },
  )
}

/**
 * Parse Karpathy's Tiny Shakespeare (`input.txt`, 1.1 MB of plays) into passages separated by blank lines, with the
 * character vocabulary and each passage as character ids, the usual character-level language-modelling corpus.
 *
 * @param bytes - The text file.
 * @returns The corpus.
 * @example
 * ```ts
 * import { parseTinyShakespeare } from 'omai-engine/datasets'
 * parseTinyShakespeare(new TextEncoder().encode('First:\nHi.\n\nSecond:\nHo.\n')).documents?.length // => 2
 * ```
 */
export function parseTinyShakespeare(bytes: Uint8Array): CorpusData {
  const text = new TextDecoder().decode(bytes)
  const vocabulary = [...new Set(text)].sort()
  const index = new Map(vocabulary.map((c, i) => [c, i]))
  const passages = text.split(/\n\s*\n/).filter((p) => p.trim() !== '')
  return corpus(
    { documents: passages, tokens: passages.map((p) => Array.from(p, (c) => index.get(c) ?? 0)), vocabulary },
    {
      name: 'tinyShakespeare',
      description: 'Tiny Shakespeare: 40000 lines of Shakespeare plays (Karpathy, char-rnn), split into passages.',
      source: 'karpathy/char-rnn data/tinyshakespeare/input.txt',
      url: 'https://github.com/karpathy/char-rnn',
      licence: 'Public domain text (MIT-licensed repository)',
    },
  )
}

/**
 * Tiny Shakespeare as a remote asset (1.1 MB) pinned by its SHA-256.
 *
 * @example
 * ```ts
 * import { tinyShakespeare } from 'omai-engine/datasets'
 * tinyShakespeare.size // => 1115394
 * ```
 */
export const tinyShakespeare: DatasetRef<CorpusData> = {
  kind: 'remote',
  name: 'tinyShakespeare',
  url: 'https://raw.githubusercontent.com/karpathy/char-rnn/master/data/tinyshakespeare/input.txt',
  sha256: '86c4e6aa9db7c042ec79f339dcb96d42b0075e16b8fc2e86bf0ca57e2dc565ed',
  size: 1_115_394,
  licence: 'Public domain text (MIT-licensed repository)',
  parse: parseTinyShakespeare,
}

/** The Jaccard similarity of the word `k`-shingles of two token lists. */
function shingleJaccard(a: readonly number[], b: readonly number[], k: number): number {
  const sh = (t: readonly number[]) => {
    const out = new Set<string>()
    for (let i = 0; i + k <= t.length; i++) out.add(t.slice(i, i + k).join(','))
    return out
  }
  const sa = sh(a)
  const sb = sh(b)
  let inter = 0
  for (const s of sa) if (sb.has(s)) inter++
  const union = sa.size + sb.size - inter
  return union === 0 ? 1 : inter / union
}

/**
 * A corpus with planted near-duplicates, for shingling, MinHash and record linkage: `nOriginals` documents of Zipfian
 * words, then `copies` near-duplicates of a share of them, each edited by word substitutions, insertions and
 * deletions at rate `editRate`. Rows are shuffled. The truth has every document's duplicate cluster, the duplicate
 * pairs with their edit counts and the exact Jaccard similarity of their 3-word shingles.
 *
 * @example
 * ```ts
 * import { generate } from 'omai-engine/data'
 * import { nearDuplicateCorpus } from 'omai-engine/datasets'
 * generate(nearDuplicateCorpus, { knobs: { nOriginals: 10, duplicated: 0.5, copies: 2 } }).data.documents?.length // => 20
 * ```
 */
export const nearDuplicateCorpus: DatasetGenerator<CorpusData> = {
  name: 'nearDuplicateCorpus',
  kind: 'corpus',
  description: 'Documents with planted near-duplicates made by random word edits.',
  knobs: dict({
    nOriginals: int(1, 100_000, {
      label: 'original documents',
      description: 'The number of original documents.',
      default: 100,
    }),
    duplicated: real(0, 1, {
      description: 'The fraction of originals that get near-duplicate copies.',
      default: 0.3,
      label: 'fraction of originals that get copies',
    }),
    copies: int(1, 20, {
      description: 'Copies of each duplicated original.',
      default: 2,
      label: 'copies per duplicated original',
    }),
    editRate: real(0, 1, {
      description: 'The chance each word of a copy is edited.',
      default: 0.1,
      label: 'per-word edit probability',
    }),
    docLength: int(3, 10_000, { label: 'document length', description: 'Words per document.', default: 60 }),
    vocabulary: int(10, 100_000, {
      label: 'vocabulary size',
      description: 'The number of distinct words.',
      default: 2000,
    }),
  }),
  generate: (k, knobs) => {
    const nOrig = knobs['nOriginals'] as number
    const v = knobs['vocabulary'] as number
    const len = knobs['docLength'] as number
    const rate = knobs['editRate'] as number
    const zipf = Array.from({ length: v }, (_, i) => 1 / (i + 1))
    const originals = Array.from({ length: nOrig }, (_, d) =>
      Array.from(categorical(foldIn(foldIn(k, 0), d), zipf, [len]).data),
    )
    const nDup = Math.round((knobs['duplicated'] as number) * nOrig)
    const copies = knobs['copies'] as number
    const docs: number[][] = originals.map((d) => [...d])
    const cluster: number[] = originals.map((_, d) => d)
    const pairs: { original: number; copy: number; edits: number; jaccard: number }[] = []
    for (let d = 0; d < nDup; d++) {
      for (let c = 0; c < copies; c++) {
        const kc = foldIn(foldIn(k, 1), d * copies + c)
        const src = originals[d] ?? []
        const u = uniform(foldIn(kc, 0), [src.length]).data
        const op = uniform(foldIn(kc, 1), [src.length]).data
        const fresh = categorical(foldIn(kc, 2), zipf, [src.length]).data
        const out: number[] = []
        let edits = 0
        for (const [i, w] of src.entries()) {
          if ((u[i] ?? 1) >= rate) {
            out.push(w)
            continue
          }
          edits++
          const o = op[i] ?? 0
          if (o < 1 / 3) out.push(fresh[i] ?? w)
          else if (o < 2 / 3) out.push(w, fresh[i] ?? w)
        }
        pairs.push({ original: d, copy: docs.length, edits, jaccard: shingleJaccard(src, out, 3) })
        docs.push(out)
        cluster.push(d)
      }
    }
    const vocab = words(v)
    const order = Array.from(uniform(foldIn(k, 2), [docs.length]).data, (x, i) => [x, i] as const)
      .sort((a, b) => a[0] - b[0])
      .map(([, i]) => i)
    const where = new Map(order.map((i, p) => [i, p]))
    const shuffled = order.map((i) => docs[i] ?? [])
    return {
      data: corpus(
        { tokens: shuffled, documents: shuffled.map((d) => d.map((w) => vocab[w] ?? '').join(' ')), vocabulary: vocab },
        stamp('nearDuplicateCorpus', nearDuplicateCorpus.description, knobs),
      ),
      truth: {
        clusters: fromStorage(
          Int32Array.from(order, (i) => cluster[i] ?? 0),
          [order.length],
          'int32',
        ),
        extra: {
          pairs: pairs.map((p) => ({ ...p, original: where.get(p.original) ?? -1, copy: where.get(p.copy) ?? -1 })),
          shingleSize: 3,
        },
      },
    }
  },
}

/**
 * A tagged corpus: sentences generated by a hidden Markov model over part-of-speech-like tags, with the tag
 * sequences as the labels and the model's tables as the truth. Each tag emits words from its own distribution, with
 * a share of the vocabulary ambiguous (emitted by two tags), so tagging a word needs its context. Transitions are
 * Dirichlet draws that are sparse when `sparsity` is small. The truth has the initial, transition and emission
 * tables for supervised estimation or to score a tagger against the Bayes tagger (Viterbi under the true tables).
 *
 * @example
 * ```ts
 * import { generate } from 'omai-engine/data'
 * import { taggedCorpus } from 'omai-engine/datasets'
 * generate(taggedCorpus, { knobs: { sentences: 5, tags: 3 } }).data.tagNames // => ['T0', 'T1', 'T2']
 * ```
 */
export const taggedCorpus: DatasetGenerator<SequenceLabellingData> = {
  name: 'taggedCorpus',
  kind: 'sequence-labelling',
  description: 'Sentences from a tag hidden Markov model with the tag sequences and the model tables as truth.',
  knobs: dict({
    sentences: int(1, 1_000_000, { label: 'sentences', description: 'The number of sentences.', default: 500 }),
    tags: int(2, 50, { label: 'tags', description: 'The number of tags (hidden states).', default: 4 }),
    vocabulary: int(4, 100_000, {
      label: 'vocabulary size',
      description: 'The number of distinct words.',
      default: 60,
    }),
    ambiguity: real(0, 1, {
      label: 'ambiguity',
      description: 'The share of words that two tags can emit.',
      default: 0.2,
    }),
    sparsity: real(0.05, 10, {
      label: 'transition concentration',
      description: 'The Dirichlet concentration of each transition row: small is near-deterministic grammar.',
      default: 0.5,
    }),
    sentenceLength: real(2, 200, {
      label: 'mean sentence length',
      description: 'The mean number of words per sentence.',
      default: 8,
    }),
  }),
  generate: (k, knobs) => {
    const ns = knobs['sentences'] as number
    const nt = knobs['tags'] as number
    const v = knobs['vocabulary'] as number
    const ambiguous = Math.round((knobs['ambiguity'] as number) * v)
    const alpha = knobs['sparsity'] as number
    const initial = Array.from(dirichlet(foldIn(k, 0), new Array<number>(nt).fill(1), 1).data)
    const transition = Array.from({ length: nt }, (_, t) =>
      Array.from(dirichlet(foldIn(foldIn(k, 1), t), new Array<number>(nt).fill(alpha), 1).data),
    )
    // Each word has an owner tag; the first `ambiguous` words are also emitted by the next tag.
    const owner = Array.from({ length: v }, (_, w) => w % nt)
    const emission = Array.from({ length: nt }, (_, t) => {
      const raw = Array.from(dirichlet(foldIn(foldIn(k, 2), t), new Array<number>(v).fill(1), 1).data)
      const masked = raw.map((p, w) => (owner[w] === t || (w < ambiguous && ((owner[w] ?? 0) + 1) % nt === t) ? p : 0))
      const z = masked.reduce((a, b) => a + b, 0)
      return masked.map((p) => p / z)
    })
    const lengths = Array.from(poisson(foldIn(k, 3), (knobs['sentenceLength'] as number) - 1, [ns]).data, (l) => l + 1)
    const vocab = words(v)
    const tokens: string[][] = []
    const tags: number[][] = []
    for (let s = 0; s < ns; s++) {
      const len = lengths[s] ?? 1
      const ks = foldIn(foldIn(k, 4), s)
      const states: number[] = []
      for (let i = 0; i < len; i++) {
        const row = i === 0 ? initial : (transition[states[i - 1] ?? 0] as number[])
        states.push(categorical(foldIn(ks, 2 * i), row, [1]).data[0] ?? 0)
      }
      tags.push(states)
      tokens.push(
        states.map(
          (t, i) => vocab[categorical(foldIn(ks, 2 * i + 1), emission[t] as number[], [1]).data[0] ?? 0] ?? '',
        ),
      )
    }
    return {
      data: sequenceLabelling(
        tokens,
        tags,
        Array.from({ length: nt }, (_, t) => `T${t}`),
        stamp('taggedCorpus', taggedCorpus.description, knobs),
      ),
      truth: { extra: { initial, transition, emission, vocabulary: vocab, owner } },
    }
  },
}

/**
 * Misspellings with their intended words: a vocabulary of pronounceable pseudo-words with Zipfian frequencies (the
 * language model), and typed words made from them by a noisy channel that deletes, inserts, substitutes or transposes
 * characters with given rates. The dataset is parallel text (typed to intended); the truth has the word frequencies,
 * the edit rates and the intended word of each typed string, for the noisy-channel spelling corrector.
 *
 * @example
 * ```ts
 * import { generate } from 'omai-engine/data'
 * import { typoPairs } from 'omai-engine/datasets'
 * generate(typoPairs, { knobs: { n: 6, errorRate: 0 } }).data.source.length // => 6
 * ```
 */
export const typoPairs: DatasetGenerator<ParallelData> = {
  name: 'typoPairs',
  kind: 'parallel',
  description: 'Typed words with the intended word, from Zipfian pseudo-words through an edit-noise channel.',
  knobs: dict({
    n: int(1, 1_000_000, { label: 'words', description: 'The number of typed words.', default: 1000 }),
    vocabulary: int(5, 20_000, {
      label: 'vocabulary size',
      description: 'The number of distinct intended words.',
      default: 300,
    }),
    errorRate: real(0, 1, {
      label: 'error rate',
      description:
        'The chance per character of an edit (a quarter each of deletion, insertion, substitution and transposition).',
      default: 0.05,
    }),
    zipf: real(0, 3, { label: 'Zipf exponent', description: 'The exponent of the word-frequency law.', default: 1 }),
  }),
  generate: (k, knobs) => {
    const n = knobs['n'] as number
    const v = knobs['vocabulary'] as number
    const rate = knobs['errorRate'] as number
    const letters = 'abcdefghijklmnopqrstuvwxyz'
    const consonants = 'bcdfghklmnprstvz'
    const vowels = 'aeiou'
    const lex = Array.from({ length: v }, (_, w) => {
      const u = uniform(foldIn(foldIn(k, 0), w), [8]).data
      const syl = 2 + Math.floor((u[0] ?? 0) * 3)
      let s = ''
      for (let i = 0; i < syl; i++)
        s +=
          (consonants[Math.floor((u[1 + 2 * (i % 3)] ?? 0) * consonants.length)] ?? 'b') +
          (vowels[Math.floor((u[2 + 2 * (i % 3)] ?? 0) * vowels.length)] ?? 'a')
      return s
    })
    // Distinct spellings: append a letter to a repeat.
    const seen = new Set<string>()
    const intended = lex.map((w, i) => {
      let s = w
      while (seen.has(s)) s += letters[i % 26] ?? 'x'
      seen.add(s)
      return s
    })
    const freq = Array.from({ length: v }, (_, w) => (w + 1) ** -(knobs['zipf'] as number))
    const z = freq.reduce((a, b) => a + b, 0)
    const prior = freq.map((f) => f / z)
    const choose = Array.from(categorical(foldIn(k, 1), prior, [n]).data)
    const source: string[] = []
    const target: string[] = []
    for (let i = 0; i < n; i++) {
      const word = intended[choose[i] ?? 0] ?? ''
      const u = uniform(foldIn(foldIn(k, 2), i), [word.length * 3 + 3]).data
      let out = ''
      for (let c = 0; c < word.length; c++) {
        const ch = word[c] ?? ''
        if ((u[3 * c] ?? 1) >= rate) {
          out += ch
          continue
        }
        const op = Math.floor((u[3 * c + 1] ?? 0) * 4)
        const rnd = letters[Math.floor((u[3 * c + 2] ?? 0) * 26)] ?? 'a'
        if (op === 0) continue // deletion
        if (op === 1)
          out += ch + rnd // insertion
        else if (op === 2)
          out += rnd // substitution
        else out += c + 1 < word.length ? `${word[c + 1]}${ch}` : ch // transposition with the next character
        if (op === 3 && c + 1 < word.length) c++
      }
      source.push(out === '' ? word : out)
      target.push(word)
    }
    return {
      data: parallel(source, target, {
        ...stamp('typoPairs', typoPairs.description, knobs),
        sourceLanguage: 'typed',
        targetLanguage: 'intended',
      }),
      truth: {
        extra: {
          vocabulary: intended,
          wordProbabilities: prior,
          errorRate: rate,
          operations: ['delete', 'insert', 'substitute', 'transpose'],
        },
      },
    }
  },
}
